TEMPLATES = {
    '404.html': '{% extends "base.html" %}\n{% block title %}Not found{% endblock %}\n{% block content %}\n<header class="page-head"><h1>We can\'t find that page</h1></header>\n<p class="empty">The product or page may have been deleted. <a href="{{ url_for(\'products\') }}">Go to products</a></p>\n{% endblock %}\n',
    '500.html': '{% extends "base.html" %}\n{% block title %}Something went wrong{% endblock %}\n{% block content %}\n<header class="page-head"><h1>Something went wrong</h1></header>\n<p class="empty">The app couldn\'t finish that request. If this keeps happening, check that\n<code>DATABASE_URL</code> is correct and the database is reachable, then look at the logs\n(in Vercel: your project, then Logs). <a href="{{ url_for(\'dashboard\') }}">Back to dashboard</a></p>\n{% if detail %}\n<section class="panel">\n  <h2>Error details</h2>\n  <pre class="errbox">{{ detail }}</pre>\n  <p class="sub">Copy this text. Remove the <code>SHOW_ERRORS</code> setting when you\'re done.</p>\n</section>\n{% endif %}\n{% endblock %}\n',
    '_macros.html': '{% macro gauge(p) %}\n{% set status = stock_status(p.quantity, p.reorder_level) %}\n{% set scale = [p.reorder_level * 3, 1]|max %}\n{% set pct = [p.quantity * 100 / scale, 100]|min %}\n<div class="gauge gauge-{{ status }}" role="img"\n     aria-label="{{ p.quantity }} in stock, reorder at {{ p.reorder_level }}">\n  <span class="gauge-fill" style="width: {{ pct }}%"></span>\n  <span class="gauge-tick" style="left: 33.33%"></span>\n</div>\n{% endmacro %}\n\n{% macro badge(p) %}\n{% set status = stock_status(p.quantity, p.reorder_level) %}\n<span class="badge badge-{{ status }}">\n  {{ {\'out\': \'Out of stock\', \'low\': \'Reorder\', \'ok\': \'In stock\'}[status] }}\n</span>\n{% endmacro %}\n',
    'base.html': '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>{% block title %}Stockroom{% endblock %} · Stockroom</title>\n  <link rel="stylesheet" href="/style.css">\n</head>\n<body class="{% block bodyclass %}{% endblock %}">\n  {% block rail %}\n  <aside class="rail">\n    <a class="brand" href="{{ url_for(\'dashboard\') }}">Stockroom</a>\n    <nav>\n      <a href="{{ url_for(\'dashboard\') }}" class="{{ \'active\' if request.endpoint == \'dashboard\' }}">Dashboard</a>\n      <a href="{{ url_for(\'products\') }}" class="{{ \'active\' if request.endpoint in (\'products\', \'product_detail\', \'product_edit\') }}">Products</a>\n      <a href="{{ url_for(\'movements\') }}" class="{{ \'active\' if request.endpoint == \'movements\' }}">Stock history</a>\n    </nav>\n    <div class="rail-foot">\n      <a href="{{ url_for(\'product_new\') }}" class="btn btn-light">Add product</a>\n      <a href="{{ url_for(\'export_csv\') }}" class="rail-link">Download CSV</a>\n      {% if auth_on and logged_in %}\n      <form method="post" action="{{ url_for(\'logout\') }}"><button class="rail-link linklike" type="submit">Sign out</button></form>\n      {% endif %}\n    </div>\n  </aside>\n  {% endblock %}\n\n  <main>\n    {% if temporary_data %}\n      <div class="flash flash-warn" role="alert">Data is stored temporarily and will reset. Connect a Postgres database to keep it (see the README section "Connect a database").</div>\n    {% endif %}\n    {% with messages = get_flashed_messages(with_categories=true) %}\n      {% for category, message in messages %}\n        <div class="flash flash-{{ category }}" role="status">{{ message }}</div>\n      {% endfor %}\n    {% endwith %}\n    {% block content %}{% endblock %}\n  </main>\n</body>\n</html>\n',
    'dashboard.html': '{% extends "base.html" %}\n{% from "_macros.html" import gauge, badge with context %}\n{% block title %}Dashboard{% endblock %}\n{% block content %}\n<header class="page-head">\n  <h1>Dashboard</h1>\n</header>\n\n<section class="stats">\n  <div class="stat">\n    <span class="stat-num">{{ totals.products }}</span>\n    <span class="stat-label">Products</span>\n  </div>\n  <div class="stat">\n    <span class="stat-num">{{ \'{:,}\'.format(totals.units) }}</span>\n    <span class="stat-label">Units on hand</span>\n  </div>\n  <div class="stat">\n    <span class="stat-num">{{ totals.value|money }}</span>\n    <span class="stat-label">Stock value</span>\n  </div>\n  <div class="stat {{ \'stat-alert\' if restock_count }}">\n    <span class="stat-num">{{ restock_count }}</span>\n    <span class="stat-label">Need restocking</span>\n  </div>\n</section>\n\n<div class="two-col">\n  <section class="panel">\n    <h2>Restock first</h2>\n    {% if needs_restock %}\n    <table>\n      <thead><tr><th>Product</th><th>Level</th><th class="num">On hand</th></tr></thead>\n      <tbody>\n      {% for p in needs_restock %}\n        <tr>\n          <td><a href="{{ url_for(\'product_detail\', product_id=p.id) }}">{{ p.name }}</a><span class="sub">{{ p.sku }}</span></td>\n          <td class="gauge-cell">{{ gauge(p) }}</td>\n          <td class="num">{{ p.quantity }} <span class="sub">of {{ p.reorder_level }} min</span></td>\n        </tr>\n      {% endfor %}\n      </tbody>\n    </table>\n    {% else %}\n      <p class="empty">Every product is above its reorder level.</p>\n    {% endif %}\n  </section>\n\n  <section class="panel">\n    <h2>Latest movements</h2>\n    {% if recent %}\n    <ul class="feed">\n      {% for m in recent %}\n      <li>\n        <span class="delta {{ \'up\' if m.delta > 0 else \'down\' }}">{{ \'%+d\'|format(m.delta) }}</span>\n        <div>\n          <a href="{{ url_for(\'product_detail\', product_id=m.product_id) }}">{{ m.name }}</a>\n          <span class="sub">{{ m.reason }} · {{ m.created_at|ts }}</span>\n        </div>\n      </li>\n      {% endfor %}\n    </ul>\n    {% else %}\n      <p class="empty">No stock has moved yet. <a href="{{ url_for(\'product_new\') }}">Add your first product.</a></p>\n    {% endif %}\n  </section>\n</div>\n{% endblock %}\n',
    'login.html': '{% extends "base.html" %}\n{% block title %}Sign in{% endblock %}\n{% block bodyclass %}bare{% endblock %}\n{% block rail %}{% endblock %}\n{% block content %}\n<div class="login-box panel">\n  <h1>Stockroom</h1>\n  <p class="sub-lead">Sign in to manage inventory.</p>\n  {% if error %}<div class="flash flash-error" role="alert">{{ error }}</div>{% endif %}\n  <form method="post" class="adjust">\n    <label>Password\n      <input type="password" name="password" required autofocus autocomplete="current-password">\n    </label>\n    <button class="btn" type="submit">Sign in</button>\n  </form>\n</div>\n{% endblock %}\n',
    'movements.html': '{% extends "base.html" %}\n{% block title %}Stock history{% endblock %}\n{% block content %}\n<header class="page-head"><h1>Stock history</h1></header>\n<section class="panel flush">\n  {% if movements %}\n  <div class="table-wrap">\n  <table>\n    <thead><tr><th>When</th><th>Product</th><th>Note</th><th class="num">Change</th></tr></thead>\n    <tbody>\n    {% for m in movements %}\n      <tr>\n        <td>{{ m.created_at|ts }}</td>\n        <td><a href="{{ url_for(\'product_detail\', product_id=m.product_id) }}">{{ m.name }}</a><span class="sub">{{ m.sku }}</span></td>\n        <td>{{ m.reason }}</td>\n        <td class="num"><span class="delta {{ \'up\' if m.delta > 0 else \'down\' }}">{{ \'%+d\'|format(m.delta) }}</span></td>\n      </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n  </div>\n  {% else %}\n    <p class="empty">Nothing has moved yet. Add or remove stock from a product page.</p>\n  {% endif %}\n</section>\n{% endblock %}\n',
    'product_detail.html': '{% extends "base.html" %}\n{% from "_macros.html" import gauge, badge with context %}\n{% block title %}{{ product.name }}{% endblock %}\n{% block content %}\n<header class="page-head">\n  <div>\n    <h1>{{ product.name }}</h1>\n    <p class="sub-lead">{{ product.sku }} · {{ product.category }}{% if product.supplier %} · {{ product.supplier }}{% endif %}</p>\n  </div>\n  <div class="head-actions">\n    <a class="btn btn-quiet" href="{{ url_for(\'product_edit\', product_id=product.id) }}">Edit product</a>\n    <form method="post" action="{{ url_for(\'product_delete\', product_id=product.id) }}"\n          onsubmit="return confirm(\'Delete {{ product.name|e }} and its stock history? This cannot be undone.\')">\n      <button class="btn btn-danger" type="submit">Delete product</button>\n    </form>\n  </div>\n</header>\n\n<div class="two-col">\n  <section class="panel">\n    <div class="big-level">\n      <span class="stat-num">{{ product.quantity }}</span>\n      <span class="stat-label">on hand · reorder at {{ product.reorder_level }}</span>\n    </div>\n    {{ gauge(product) }}\n    <p>{{ badge(product) }}\n      <span class="sub">Worth {{ (product.quantity * product.unit_price)|money }} at {{ product.unit_price|money }} each</span></p>\n\n    <h2>Update stock</h2>\n    <form method="post" action="{{ url_for(\'product_adjust\', product_id=product.id) }}" class="adjust">\n      <label>Amount\n        <input name="amount" type="number" min="1" step="1" required>\n      </label>\n      <label>Note (optional)\n        <input name="reason" placeholder="e.g. Delivery from supplier, Order #1042">\n      </label>\n      <div class="form-actions">\n        <button class="btn" name="direction" value="in" type="submit">Add stock</button>\n        <button class="btn btn-quiet" name="direction" value="out" type="submit">Remove stock</button>\n      </div>\n    </form>\n  </section>\n\n  <section class="panel">\n    <h2>History</h2>\n    {% if history %}\n    <ul class="feed">\n      {% for m in history %}\n      <li>\n        <span class="delta {{ \'up\' if m.delta > 0 else \'down\' }}">{{ \'%+d\'|format(m.delta) }}</span>\n        <div>{{ m.reason }}<span class="sub">{{ m.created_at|ts }}</span></div>\n      </li>\n      {% endfor %}\n    </ul>\n    {% else %}\n      <p class="empty">No stock movements yet. Add or remove stock to start the history.</p>\n    {% endif %}\n  </section>\n</div>\n{% endblock %}\n',
    'product_form.html': '{% extends "base.html" %}\n{% block title %}{{ \'Edit product\' if editing else \'Add product\' }}{% endblock %}\n{% block content %}\n<header class="page-head">\n  <h1>{{ \'Edit product\' if editing else \'Add product\' }}</h1>\n</header>\n\n{% if errors %}\n<div class="flash flash-error" role="alert">\n  <ul>{% for e in errors %}<li>{{ e }}</li>{% endfor %}</ul>\n</div>\n{% endif %}\n\n<form method="post" class="panel form-grid">\n  <label>SKU\n    <input name="sku" value="{{ product.sku or \'\' }}" required autofocus>\n  </label>\n  <label>Product name\n    <input name="name" value="{{ product.name or \'\' }}" required>\n  </label>\n  <label>Category\n    <input name="category" value="{{ product.category or \'\' }}" placeholder="General">\n  </label>\n  <label>Supplier\n    <input name="supplier" value="{{ product.supplier or \'\' }}">\n  </label>\n  <label>Quantity on hand\n    <input name="quantity" type="number" min="0" step="1" value="{{ product.quantity if product.quantity is not none else 0 }}">\n  </label>\n  <label>Reorder level\n    <input name="reorder_level" type="number" min="0" step="1" value="{{ product.reorder_level if product.reorder_level is not none else 10 }}">\n    <small>You\'ll see a reorder warning at or below this number.</small>\n  </label>\n  <label>Unit price\n    <input name="unit_price" type="number" min="0" step="0.01" value="{{ product.unit_price if product.unit_price is not none else 0 }}">\n  </label>\n  <div class="form-actions">\n    <button class="btn" type="submit">{{ \'Save changes\' if editing else \'Add product\' }}</button>\n    <a class="btn btn-quiet" href="{{ url_for(\'product_detail\', product_id=product_id) if editing else url_for(\'products\') }}">Cancel</a>\n  </div>\n</form>\n{% endblock %}\n',
    'products.html': '{% extends "base.html" %}\n{% from "_macros.html" import gauge, badge with context %}\n{% block title %}Products{% endblock %}\n{% block content %}\n<header class="page-head">\n  <h1>Products</h1>\n  <a href="{{ url_for(\'product_new\') }}" class="btn">Add product</a>\n</header>\n\n<form class="filters" method="get">\n  <input type="search" name="q" value="{{ q }}" placeholder="Search name, SKU or supplier" aria-label="Search products">\n  <select name="category" aria-label="Category">\n    <option value="">All categories</option>\n    {% for c in categories %}\n      <option value="{{ c }}" {{ \'selected\' if c == category }}>{{ c }}</option>\n    {% endfor %}\n  </select>\n  <select name="status" aria-label="Stock status">\n    <option value="">Any stock level</option>\n    <option value="ok" {{ \'selected\' if status == \'ok\' }}>In stock</option>\n    <option value="low" {{ \'selected\' if status == \'low\' }}>Reorder</option>\n    <option value="out" {{ \'selected\' if status == \'out\' }}>Out of stock</option>\n  </select>\n  <button class="btn btn-quiet" type="submit">Apply filters</button>\n</form>\n\n<section class="panel flush">\n  {% if products %}\n  <div class="table-wrap">\n  <table>\n    <thead>\n      <tr><th>Product</th><th>Category</th><th>Level</th><th class="num">On hand</th><th class="num">Unit price</th><th>Status</th></tr>\n    </thead>\n    <tbody>\n    {% for p in products %}\n      <tr>\n        <td><a href="{{ url_for(\'product_detail\', product_id=p.id) }}">{{ p.name }}</a><span class="sub">{{ p.sku }}</span></td>\n        <td>{{ p.category }}</td>\n        <td class="gauge-cell">{{ gauge(p) }}</td>\n        <td class="num">{{ p.quantity }}</td>\n        <td class="num">{{ p.unit_price|money }}</td>\n        <td>{{ badge(p) }}</td>\n      </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n  </div>\n  {% elif q or category or status %}\n    <p class="empty">No products match these filters. <a href="{{ url_for(\'products\') }}">Clear filters</a></p>\n  {% else %}\n    <p class="empty">No products yet. <a href="{{ url_for(\'product_new\') }}">Add your first product.</a></p>\n  {% endif %}\n</section>\n{% endblock %}\n',
}

STYLE_CSS = ':root {\n  --ink: #14232f;\n  --ink-soft: #52616d;\n  --surface: #edf0f2;\n  --panel: #ffffff;\n  --line: #d9dfe4;\n  --rail: #14232f;\n  --primary: #0e6e6e;\n  --primary-dark: #0a5555;\n  --warn: #c98200;\n  --warn-bg: #fdf1d6;\n  --bad: #b83232;\n  --bad-bg: #fbe4e2;\n  --ok-bg: #dcf0ed;\n  --radius: 6px;\n  --font: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;\n}\n\n*, *::before, *::after { box-sizing: border-box; }\nhtml { font-size: 16px; }\nbody {\n  margin: 0;\n  display: grid;\n  grid-template-columns: 220px 1fr;\n  min-height: 100vh;\n  font-family: var(--font);\n  color: var(--ink);\n  background: var(--surface);\n  line-height: 1.5;\n}\n\na { color: var(--primary); text-decoration-thickness: 1px; text-underline-offset: 2px; }\na:hover { color: var(--primary-dark); }\n:focus-visible { outline: 3px solid #2aa6a6; outline-offset: 2px; }\n\n/* ---------- side rail ---------- */\n.rail {\n  background: var(--rail);\n  color: #e7edf1;\n  display: flex;\n  flex-direction: column;\n  padding: 1.5rem 1rem;\n  position: sticky;\n  top: 0;\n  height: 100vh;\n}\n.brand {\n  color: #fff;\n  font-size: 1.35rem;\n  font-weight: 700;\n  letter-spacing: -0.01em;\n  text-decoration: none;\n  padding: 0 0.6rem 1.5rem;\n}\n.rail nav { display: flex; flex-direction: column; gap: 2px; }\n.rail nav a {\n  color: #b9c6cf;\n  text-decoration: none;\n  padding: 0.55rem 0.6rem;\n  border-radius: var(--radius);\n  border-left: 3px solid transparent;\n}\n.rail nav a:hover { background: #1d3140; color: #fff; }\n.rail nav a.active { background: #1d3140; color: #fff; border-left-color: #3fc1b4; }\n.rail-foot { margin-top: auto; display: flex; flex-direction: column; gap: 0.75rem; padding: 0 0.2rem; }\n.rail-link { color: #b9c6cf; font-size: 0.9rem; padding-left: 0.4rem; }\n.rail-link:hover { color: #fff; }\n\n/* ---------- main ---------- */\nmain { padding: 2rem 2.5rem 4rem; max-width: 1100px; width: 100%; }\n.page-head {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  gap: 1rem;\n  margin-bottom: 1.5rem;\n}\nh1 { font-size: 1.75rem; line-height: 1.2; margin: 0; letter-spacing: -0.015em; }\nh2 { font-size: 1.05rem; margin: 0 0 1rem; }\n.sub-lead { margin: 0.25rem 0 0; color: var(--ink-soft); }\n.sub { display: block; font-size: 0.82rem; color: var(--ink-soft); }\n.head-actions { display: flex; gap: 0.5rem; }\n\n/* ---------- buttons ---------- */\n.btn {\n  display: inline-block;\n  font: inherit;\n  font-weight: 600;\n  font-size: 0.92rem;\n  padding: 0.5rem 1rem;\n  border-radius: var(--radius);\n  border: 1px solid var(--primary);\n  background: var(--primary);\n  color: #fff;\n  text-decoration: none;\n  cursor: pointer;\n  text-align: center;\n}\n.btn:hover { background: var(--primary-dark); border-color: var(--primary-dark); color: #fff; }\n.btn-quiet { background: transparent; color: var(--ink); border-color: #aab5bd; }\n.btn-quiet:hover { background: #e2e7ea; color: var(--ink); border-color: #8d9aa4; }\n.btn-light { background: #e7edf1; border-color: #e7edf1; color: var(--ink); }\n.btn-light:hover { background: #fff; border-color: #fff; color: var(--ink); }\n.btn-danger { background: transparent; color: var(--bad); border-color: #d9a5a5; }\n.btn-danger:hover { background: var(--bad-bg); color: var(--bad); border-color: var(--bad); }\n\n/* ---------- panels, stats ---------- */\n.panel {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 1.25rem 1.4rem;\n}\n.panel.flush { padding: 0; overflow: hidden; }\n.two-col { display: grid; grid-template-columns: 1.4fr 1fr; gap: 1.25rem; align-items: start; }\n\n.stats {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  margin-bottom: 1.25rem;\n}\n.stat { padding: 1.1rem 1.4rem; border-left: 1px solid var(--line); display: flex; flex-direction: column; }\n.stat:first-child { border-left: 0; }\n.stat-num { font-size: 1.9rem; font-weight: 700; line-height: 1.15; font-variant-numeric: tabular-nums; }\n.stat-label { font-size: 0.88rem; color: var(--ink-soft); }\n.stat-alert .stat-num { color: var(--bad); }\n\n/* ---------- tables ---------- */\n.table-wrap { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 0.75rem 1rem; vertical-align: middle; }\nthead th { font-size: 0.85rem; font-weight: 600; color: var(--ink-soft); border-bottom: 1px solid var(--line); background: #f7f9fa; }\ntbody tr + tr td { border-top: 1px solid #edf0f2; }\ntbody tr:hover { background: #f9fbfb; }\n.num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }\n.panel:not(.flush) th, .panel:not(.flush) td { padding-left: 0; }\n.panel:not(.flush) th:last-child, .panel:not(.flush) td:last-child { padding-right: 0; }\n.gauge-cell { width: 28%; min-width: 120px; }\n\n/* ---------- stock gauge: bar fills toward 3x the reorder level, tick marks the reorder level ---------- */\n.gauge {\n  position: relative;\n  height: 10px;\n  background: #e4e9ec;\n  border-radius: 2px;\n  overflow: visible;\n}\n.gauge-fill { position: absolute; inset: 0 auto 0 0; border-radius: 2px; background: var(--primary); }\n.gauge-low .gauge-fill { background: var(--warn); }\n.gauge-out .gauge-fill { background: var(--bad); }\n.gauge-tick { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--ink); opacity: 0.55; }\n.big-level + .gauge { margin: 0.5rem 0 1rem; height: 14px; }\n.big-level { display: flex; align-items: baseline; gap: 0.6rem; }\n\n.badge { display: inline-block; font-size: 0.8rem; font-weight: 600; padding: 0.1rem 0.55rem; border-radius: 99px; }\n.badge-ok { background: var(--ok-bg); color: #0a5555; }\n.badge-low { background: var(--warn-bg); color: #7d5100; }\n.badge-out { background: var(--bad-bg); color: var(--bad); }\n\n/* ---------- feeds ---------- */\n.feed { list-style: none; margin: 0; padding: 0; }\n.feed li { display: flex; gap: 0.9rem; padding: 0.6rem 0; align-items: flex-start; }\n.feed li + li { border-top: 1px solid #edf0f2; }\n.delta { font-weight: 700; font-variant-numeric: tabular-nums; min-width: 3rem; }\n.delta.up { color: var(--primary); }\n.delta.down { color: var(--bad); }\n\n.empty { padding: 1.5rem; color: var(--ink-soft); margin: 0; }\n.panel:not(.flush) .empty { padding: 0.5rem 0; }\n\n/* ---------- forms ---------- */\n.filters { display: flex; flex-wrap: wrap; gap: 0.6rem; margin-bottom: 1rem; }\n.filters input[type=search] { flex: 1 1 240px; }\ninput, select {\n  font: inherit;\n  padding: 0.5rem 0.7rem;\n  border: 1px solid #aab5bd;\n  border-radius: var(--radius);\n  background: #fff;\n  color: var(--ink);\n  width: 100%;\n}\n.filters input, .filters select { width: auto; }\n.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.1rem 1.5rem; max-width: 720px; }\n.form-grid label, .adjust label { display: flex; flex-direction: column; gap: 0.3rem; font-weight: 600; font-size: 0.92rem; }\nlabel small { font-weight: 400; color: var(--ink-soft); }\n.form-actions { display: flex; gap: 0.6rem; grid-column: 1 / -1; }\n.adjust { display: flex; flex-direction: column; gap: 0.9rem; }\n\n/* ---------- flash ---------- */\n.flash { padding: 0.7rem 1rem; border-radius: var(--radius); margin-bottom: 1.25rem; border: 1px solid; }\n.flash ul { margin: 0; padding-left: 1.1rem; }\n.flash-ok { background: var(--ok-bg); border-color: #9fd3cc; color: #07423f; }\n.flash-error { background: var(--bad-bg); border-color: #e3aaa6; color: #7d1f1f; }\n\n/* ---------- small screens ---------- */\n@media (max-width: 860px) {\n  body { grid-template-columns: 1fr; }\n  .rail { position: static; height: auto; flex-direction: row; flex-wrap: wrap; align-items: center; gap: 0.5rem 1rem; padding: 0.8rem 1rem; }\n  .brand { padding: 0; }\n  .rail nav { flex-direction: row; }\n  .rail nav a { border-left: 0; border-bottom: 3px solid transparent; border-radius: 0; }\n  .rail nav a.active { border-bottom-color: #3fc1b4; }\n  .rail-foot { margin: 0 0 0 auto; flex-direction: row; align-items: center; }\n  main { padding: 1.25rem 1rem 3rem; }\n  .two-col, .form-grid { grid-template-columns: 1fr; }\n  .stats { grid-template-columns: 1fr 1fr; }\n  .stat:nth-child(3) { border-left: 0; }\n  .stat:nth-child(n+3) { border-top: 1px solid var(--line); }\n  .page-head { flex-direction: column; }\n}\n@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }\n\n/* ---------- login, warnings, small additions ---------- */\n.flash-warn { background: var(--warn-bg); border-color: #e6c36e; color: #6a4500; }\n.linklike { background: none; border: 0; font: inherit; cursor: pointer; text-align: left; padding: 0 0 0 0.4rem; }\nbody.bare { display: block; }\nbody.bare main { margin: 0 auto; padding-top: 12vh; max-width: 420px; }\n.login-box h1 { margin-bottom: 0.25rem; }\n.login-box .sub-lead { margin-bottom: 1.25rem; }\n.login-box .btn { width: 100%; }\ncode { background: #e4e9ec; padding: 0.05rem 0.35rem; border-radius: 3px; font-size: 0.9em; }\n\n.errbox { background: #14232f; color: #e7edf1; padding: 0.9rem 1rem; border-radius: var(--radius); white-space: pre-wrap; word-break: break-word; font-size: 0.88rem; margin: 0 0 0.75rem; }\n'
